function setV1(ad) { const s = JSON.parse(fs.readFileSync(path.join(KOK, 'tests', ad), 'utf8')); s.istemler = s.istemler.filter(i => !i.dog1); s.receteler = s.receteler.filter(r => !r.dog1); return s; }
