const argv = process.argv.slice(2);
function arg(ad) {
  const a = argv.find(x => x === '--' + ad || x.startsWith('--' + ad + '='));
  if (!a) return null;
  return a.includes('=') ? a.split('=').slice(1).join('=') : true;
}
